/* 命之轨迹TRPG 角色卡创建工具 - 规则数据 Part 2
   技能树/通用天赋/装备/战技 */

// ============ 核心技能 1 阶天赋 ============
const SKILL_TREES = [
  {"skill":"徒手","intro":"拳打、脚踢和斗殴，你将进行一次徒手格斗检定，以拳、脚、爪和牙齿进行攻击。徒手格斗技能包括徒手格斗和一些武术能力。","adv":["粉碎打击。 为你的伤害奖励骰增加1点蓄势。","眩晕打击。 你不对负伤的对手造成生命值伤害，转而使其昏迷。","隐蔽打击。 你的攻击不露痕迹，对此进行的防御尝试具有1挑战。"],"type":"武器","t1":"徒手格斗初学者","effect":"徒手攻击与行动检定 +1 奖励骰；可学基础/初学者徒手技法","nodes":[{"name":"徒手格斗初学者","rank":1,"prereq":[],"desc":"所有徒手格斗攻击和行动骰获得+1奖励骰。你可以使用任何基础技法配合徒手格斗打击，并学习徒手格斗初学者技法。"},{"name":"开掌","rank":2,"prereq":["徒手格斗初学者"],"desc":"在完全徒手战斗时，使用你的手和脚进行的副手攻击，仅在命中和伤害上受到1挑战减值。"},{"name":"强健","rank":2,"prereq":["徒手格斗初学者"],"desc":"严苛的训练磨练了你的身体，增强了你的不竭。你的耐力值+4。","resource":{"sta":4}},{"name":"寸劲","rank":2,"prereq":["徒手格斗初学者"],"desc":"当你装备指虎或拳套武器时，你可以利用诸如轻巧或迅捷等特性。"},{"name":"迅捷打击","rank":3,"prereq":["开掌"],"desc":"你以流畅的狂怒与优雅进行打击。当处于徒手状态时，进行徒手格斗副手攻击的活力消耗减少3点。"},{"name":"徒手格斗专家","rank":3,"prereq":["强健"],"desc":"当你进行徒手格斗攻击和行动骰时，你添加+1奖励骰（总计+2）。你可以学习专家级徒手技法。"},{"name":"坚实打击","rank":3,"prereq":["寸劲"],"desc":"你的徒手格斗攻击蕴含压倒性的强力。你的徒手攻击获得冲击特性。"},{"name":"要害打击","rank":4,"prereq":["迅捷打击"],"desc":"你的攻击如致命节奏般流畅。当你对未着甲或仅着轻甲的目标进行徒手攻击且有机会造成伤害时，你的基础徒手攻击武器伤害翻倍。"},{"name":"二连打击","rank":4,"prereq":["迅捷打击"],"desc":"轻松衔接徒手攻击。在完全徒手战斗时，你用空手或脚发动的副手攻击，其徒手攻击或伤害奖励骰不会承受挑战惩罚。"},{"name":"额外行动","rank":4,"prereq":["徒手格斗专家"],"desc":"你在你的回合中获得1个额外行动。"},{"name":"铁手","rank":4,"prereq":["坚实打击"],"desc":"你的徒手攻击力道极大，能将力量深透目标，轻易击碎砖块木板。你的徒手攻击获得粉碎特性，并对无生命物体和护甲造成双倍伤害。"},{"name":"铁腕","rank":4,"prereq":["坚实打击"],"desc":"当你使用指节铜套或臂铠等拳套武器格挡攻击时，将你的武器伤害加到伤害吸收上。"},{"name":"死亡之触","rank":5,"prereq":["要害打击"],"desc":"当你用徒手攻击造成伤害时，你可以牺牲伤害掷骰中的奖励骰，每牺牲1颗奖励骰，便直接对生命值或完整性造成3点伤害。"},{"name":"千拳连打","rank":5,"prereq":["二连打击"],"desc":"你的拳脚获得迅捷武器特性。在你的回合内，如果你连续进行2次徒手攻击或技法行动，你可以额外进行一次徒手攻击行动。"},{"name":"徒手大师","rank":5,"prereq":["额外行动"],"desc":"当你进行徒手攻击和徒手行动检定时，你获得+1奖励骰（总计+3）。你技艺精湛，足以学习大师级徒手技法。"},{"name":"碎骨拳","rank":5,"prereq":["铁手"],"desc":"你的徒手攻击极为致命。将你的基础徒手伤害提升至普通（1d8），而非低劣（1d6）"},{"name":"崩山拳","rank":5,"prereq":["铁腕"],"desc":"以不屈之力猛击。当你使用徒手武器进行徒手攻击或技法并造成伤害时，若目标为中型或更小，你将其击退5尺。更大的目标免疫此效果，但承受双倍武器伤害。"}]},
  {"skill":"抵抗","intro":"以抵抗来克服与忍耐，这是你抵御物理、精神和心灵侵袭的盾牌。当你遭受无法闪避的精神、魔法或物理侵袭时，你可以使用反应行动进行一次抵抗检定，以尽量降低或完全克服这次攻击。 **特殊：** 抵抗反应。除非另有说明，每当遭受非武器效应造成的侵袭时，你都可以进行抵抗反应。存在数种抵抗技法，例如忍耐、克服和反制法术。尝试抵抗会消耗5点魔力。","adv":[],"type":"反应","t1":"抵抗初学者","effect":"抵抗反应 +1 奖励骰；可使用忍耐/克服技法","nodes":[{"name":"抵抗初学者","rank":1,"prereq":[],"desc":"在所有用于克服或闪避侵袭的抵抗反应中，添加+1奖励骰。你可以使用所有基础抵抗技法，例如忍耐和克服。"},{"name":"坚定心灵","rank":2,"prereq":["抵抗初学者"],"desc":"你的心灵坚不可摧，抵御入侵。增加你的决心值+4。","resource":{"rsl":4}},{"name":"护甲导能","rank":2,"prereq":["抵抗初学者"],"desc":"穿戴中型或重型护甲时，当进行抵抗反应或施放咒语时，传导惩罚（护甲状态下增加魔力消耗或阻止施法的干扰效应）减少3点。"},{"name":"钢铁韧性","rank":2,"prereq":["抵抗初学者"],"desc":"你的躯体能忍受毒素和痛苦。你的耐力值+4。","resource":{"sta":4}},{"name":"坚韧意志","rank":3,"prereq":["坚定心灵"],"desc":"你承受的负担越重，你挣脱困境的决心就越坚定。当你处于灼烧、冻结、流血、恍惚、迷眩、中毒、封技或封魔的影响下时，你的魔法屏障增加+10。"},{"name":"精神护盾","rank":3,"prereq":["坚定心灵"],"desc":"即使你精神抵抗检定失败，你也不会被完全压制，并且精神侵袭的持续时间减半。"},{"name":"抵抗专家","rank":3,"prereq":["护甲导能"],"desc":"当你进行任何抵抗掷骰时，+1奖励骰（总计+2）。"},{"name":"强韧体魄","rank":3,"prereq":["钢铁韧性"],"desc":"当你对毒素、疾病或环境伤害的抵抗检定失败时，额外减少等同于你抵抗奖励骰数量3倍的伤害。例如，若你从抵抗专家获得了+2个抵抗奖励骰，你最多可减轻6点伤害。"},{"name":"浴血专注","rank":3,"prereq":["钢铁韧性"],"desc":"当情况变得危急时，你拥有克服万难存活下去的意志。当你处于负伤状态时，你的魔法屏障增加+10。"},{"name":"精神要塞","rank":4,"prereq":["精神护盾"],"desc":"你的内心是一座坚城。在成功抵抗精神侵袭后，你获得对恍惚、迷眩和魅惑的临时免疫，直到你的下一个回合。"},{"name":"一息尚存","rank":4,"prereq":["抵抗专家"],"desc":"你拥有抵抗死亡的坚韧。当你的生命值降为0时，你可以进行一次抵抗反应，VS 45。若成功，你保留1点生命值并保持清醒。此能力可使用一次，并在完整休息后恢复使用次数。"},{"name":"钢铁之肤","rank":4,"prereq":["强韧体魄"],"desc":"你的肌肤在压力下硬化。在成功抵抗物理侵袭后，你获得临时护甲等级，其数值等于你抵抗奖励骰的两倍，该效果适用于在你的下一个回合前第一次针对你的物理攻击。"},{"name":"心灵堡垒","rank":5,"prereq":["精神要塞"],"desc":"你的专注与心灵已成为坚不可摧的堡垒。你免疫任何抵抗VS低于你的决心值的精神侵袭。"},{"name":"抵抗大师","rank":5,"prereq":["一息尚存"],"desc":"当你进行任何抵抗检定时，获得+1奖励骰（总计+3）。你可以学习大师级抵抗技法。"},{"name":"噬毒者","rank":5,"prereq":["钢铁之肤"],"desc":"当你承受着持续的毒素或毒药效果时，你可以用一个行动，以三次冒险尝试进行一次抵抗（体能）检定。若成功，你消耗10点魔力并代谢该毒素，终止这一效应。此外，你恢复1d8点生命与2D6点耐久。"}]},
  {"skill":"科学与技术","intro":"理解系统、操作、设计与修理复杂的机械和电脑，需要进行科学与技术检定。这涵盖了一般性的技术知识与维修，以及精深的科学与工程学。导力工程学亦属于此项技能。","adv":["耐久修复。 将耐久修复骰的品质提升1级。","创新技术。 修复损坏的技术部件时，你可以将其品质提升1级。","时间效率。 减少工程任务所需时间20%。"],"type":"学术","t1":"初学者技师","effect":"科技行动检定 +1 奖励骰；可使用技术蓝图","nodes":[{"name":"初学者技师","rank":1,"prereq":[],"desc":"为所有科学与技术行动检定（机器、实验或系统操作）增加+1奖励骰。你可以使用任何技术蓝图，并学习初学者蓝图。"},{"name":"研究","rank":2,"prereq":["初学者技师"],"desc":"你以科学严谨的态度记录每一次实验、观察和异常现象。一旦你在特定场景中尝试了一次科学与技术行动，在同一场景、环境或主题内，任何后续相关的科学与技术检定都会获得+1奖励骰（由GM决定）。 此外，当你在有充裕时间（例如一整天或在休整期）进行科学与技术行动时，你可以进行1次冒险而不增加VS，这代表着你经过深思熟虑的研究和先前发现的运用。"},{"name":"修理","rank":2,"prereq":["初学者技师"],"desc":"你的双手知道如何将东西重新组装起来。当你进行科技和科学检定以修理或维护装备时，你可以为受损的护甲或载具恢复双倍的耐久。"},{"name":"回收利用","rank":2,"prereq":["初学者技师"],"desc":"你能在旧零件中发现新用途。只要你能获得零件，就可以利用它们进行修理或建造。你可以用可用零件替代核心组件，品质降低1级；也可以用核心组件替代同品质的可用零件。你可以将机器和装置拆解为1d4个可用零件和1个与原始设备品质相同的核心组件。"},{"name":"便携实验室","rank":3,"prereq":["研究"],"desc":"你维护着一套紧凑的实验室工具包，并知道如何利用备用设备临时搭建一个完整的研究站，从而在野外进行高级分析和实验。以游戏术语来说，当你使用你的便携实验室进行调查或合成材料时，你在科学与技术检定上获得 +1 奖励骰。"},{"name":"专家技师","rank":3,"prereq":["修理"],"desc":"你的专长更为精进。在所有科学与技术掷骰上增加 +1 奖励骰（总计 +2）。你可以学习专家蓝图。"},{"name":"工具包","rank":3,"prereq":["回收利用"],"desc":"你携带了一套专业工具。当你组装好一个工具包后，你使用自制的工具包进行建造或修理设备的科学与技术检定时，你获得 +1 奖励骰。"},{"name":"应用科学","rank":4,"prereq":["便携实验室"],"desc":"你专门研究一个科学学科，拥有将科学发现转化为可操作的工具的知识和交流技巧，从而为你和你的盟友所用。选择一项科学领域： *材料科学：* 你合成的化合物、化学品、炸药、酸类及材料，其品质总是提升 1 个等级。 *物理科学：* 在解决工程或力学相关问题时，只要你花时间进行计算，你获得 1 次免费蓄势用于科学与技术检定。 *生命科学：* 只要你拥有适当的工具或药品，你在医学检定上获得 1 次免费蓄势。 *药理学：* 你制造的药物化合物品质提升 1 个等级。 此外，每当你成功进行一项涉及所选领域的科学与技术检定时，你可以生成一份研究简报。你可以将其分享给他人（或之后自己参考），为参考该简报进行的单次相关行动掷骰提供 +1 奖励骰。"},{"name":"系统覆写","rank":4,"prereq":["便携实验室"],"desc":"你是代码、计算和机器逻辑的大师。你设计的程序、操作系统、模拟和AI构装品质量+1级。当你能够使用你的终端或操控台时，你进行的涉及加密、破译、模拟、算法优化或合成智能的科学与技术检定获得1点免费蓄势。 此外，当你成功通过一次相关的科学与技术检定后，你可以创建一个数字化协议。数字化协议是一个可重复使用的子程序或模板，当它被引用时，它为你或盟友在相关的数字化或计算任务上提供+1奖励骰。每次行动只能使用一个此类协议。"},{"name":"技术思维","rank":4,"prereq":["专家技师"],"desc":"你已经培养出解决技术问题的思维。你的理性与记忆属性值各增加 +4。","resource":{"rea":4,"mem":4}},{"name":"电气工程","rank":4,"prereq":["工具包"],"desc":"你专精于电路、电力传输、传感器和逻辑驱动硬件。你制造的电子设备默认质量+1级。当你修复或对接电气或奥术电路时，你可以重投奖励骰中出现的任何1点。"},{"name":"机械工程","rank":4,"prereq":["工具包"],"desc":"你专精于建造和修复物理系统：引擎、液压装置、齿轮和动力框架。你制造的机器默认质量+1级。你修复的机器、载具和装置恢复双倍的耐久或完整性。"},{"name":"科学突破","rank":5,"prereq":["应用科学"],"desc":"在使用实验室进行科学与技术检定时，尝试创造或分析时，你可以消耗2次冒险来触发突破。突破允许你绕过通常无法逾越的限制（例如不稳定材料、动力源要求、未知组件），具体由GM决定。"},{"name":"量子架构师","rank":5,"prereq":["系统覆写"],"desc":"你是抽象系统、合成心智以及信息本身的大师。你能以媲美神圣逻辑的优雅操纵算法。每次完整休息后最多一次，如果一项数字任务的VS等于或低于你的理性值，并且你能够使用已连接的接口或工具组，你可以瞬间完成它（无需检定）。你可以同时维持2个激活的数字协议。如果相关，两者可在同一行动中使用，提供共计+2奖励骰。"},{"name":"技术大师","rank":5,"prereq":["技术思维"],"desc":"你的头脑是发明的源泉。所有科学与技术掷骰获得+1奖励骰（总计+3）。你可以学习大师级创新技法。"},{"name":"覆写","rank":5,"prereq":["电气工程"],"desc":"你可以夺取任何电子或奥术逻辑系统的控制权。通过1d6分钟的工作，你可以尝试一次VS 40的科学与技术检定，消耗1个可用零件来绕过机器的原生编程并下达新指令（例如打开密封门、关闭炮塔、夺取无人机控制）。你还可以触发被控制系统或敌对构造的自毁，造成等同于其动力源或伤害骰的爆炸效应（GM决定）。"},{"name":"超频","rank":5,"prereq":["机械工程"],"desc":"你使用粗犷的零件与不顾一切的天才智慧，驱动机械超越其极限。执行此操作至少需要2d6分钟，以及一次VS 40的科学与技术检定，并需要消耗一个核心组件。在接下来的2分钟内，你粗暴的升级有效提升机器的品质1个等级。这将根据机器的类型增加其速度、伤害、射程或其他因素。使用后，机器承受5d8耐久伤害。"}]},
  {"skill":"医学","intro":"医学原理是自然哲学和科学最古老的形式之一。现代医学需要解剖学、生物学、化学和伦理学的广泛训练。医学技能包括医疗和外科手术，以及医学专科和药理学。","adv":["治愈之触。 将你的急救治疗骰的等级提高1，即使它们不是奖励骰。","快速治疗。 减少急救所需时间至1个行动。","综合护理。 减少医疗程序所需时间20%。"],"type":"学术","t1":"初学者治疗","effect":"医学检定 +1 奖励骰；急救（2 行动，VS 20）恢复 1d10 耐久","nodes":[{"name":"初学者治疗","rank":1,"prereq":[],"desc":"你的医学技能达到高级水平。使用现代药物、药品、缝针、缝合线和抗生素进行医学检定时，增加+1奖励骰。在你的照料下，患者每夜睡眠后每日恢复+2d4生命值。通过一次医学（治疗）检定 VS 20，你可以花费2个行动进行急救，通过清理和包扎伤口使受伤角色恢复1d10耐久。"},{"name":"医学专精","rank":2,"prereq":["初学者治疗"],"desc":"你已成为医学和治疗领域（如外科学或内科学）的专家。选择以下专长之一。 现代外科学。你是一名外科专家。成功通过一次医学（治疗）检定，你便可实施复杂的、能挽救生命的外科手术。实际上，成功的手术检定可以稳定一名濒死或新近因伤死亡的患者，并使其伤势在1d4周内恢复。在短休期间，你可以为每个患者每日恢复一次1d10点耐久，或1d8点生命值。 遗传学。你是遗传学与表观遗传学研究的专家。成功通过一次医学（治疗）检定，你可以制作特定的基因疗法，以治疗疾病，并在技术许可的情况下对患者进行强化。从实用角度上，如果有足够的实验室，你可以治愈或逆转某些遗传状态和疾病。 内科学。你专精于内科学和毒理学。当你治疗患有疾病或中毒的生物时，他们在你的护理下进行抵抗任何病痛或疾病的抵抗检定时，会额外获得+1奖励骰。"},{"name":"战地医师","rank":3,"prereq":["医学专精"],"desc":"你天生适合在恶劣环境中进行高压救护。作为伤害或疾病的第一响应者，你知道如何治疗伤口、中毒以及可能致命的突发状况。作为一个行动，你可以进行一次医学检定 VS 20，对相邻生物进行急救，通过包扎伤口恢复2d10耐久，或提供+1奖励骰，用于以抵抗克服疾病或中毒。"},{"name":"专家治疗","rank":3,"prereq":["医学专精"],"desc":"你擅长诊断、治疗和预防伤害或疾病。你为你的医学检定增加+1奖励骰，总计+2。"},{"name":"护理专家","rank":3,"prereq":["医学专精"],"desc":"你擅长持续性、恢复性的治疗。在你的照料下，患者通过一夜休息额外恢复+2d4生命，同时在那次休息期间进行的抵抗渐进性疾病或毒药的抵抗检定获得+1奖励骰。"},{"name":"危机干预","rank":4,"prereq":["战地医师"],"desc":"你能让某人超越极限继续行动。当你使用一个行动对负伤目标进行急救时，你可以使负伤状态的效应失效1d4回合，并恢复1d4生命。"},{"name":"诊断洞察","rank":4,"prereq":["专家治疗"],"desc":"你的洞察提升了你的推理能力。你的理性属性值增加+8。","resource":{"rea":8}},{"name":"细致治疗","rank":4,"prereq":["护理专家"],"desc":"你能处理复杂的多系统伤病。在休整期期间，你可以在通常治疗一个状态或一名患者所需的时间里，治疗两个不同的状态或两名不同的患者。"},{"name":"前线奇迹","rank":5,"prereq":["危机干预"],"desc":"你可以把生物从必死的境地中救回来。当你身边的一名盟友将被一次攻击或物理侵袭杀死时，你可以用一个反应行动进行一次医学检定 VS 40。成功时，该盟友会保持活动状态，但生命值为1。在你的回合，你可以用一个行动进行一次医学检定 VS 50，并治疗一个在过去4轮（一分钟）内死于攻击或侵袭的生物，使其稳定在0生命值。但这需要付出某些牺牲。获救的生物会遭受某种永久性创伤或留下疤痕。由GM决定，或者直接将其一项身体或心智属性值降低 1d4，或将其一项资源（耐久、生命值、魔力、活力）降低 2d4。"},{"name":"治疗大师","rank":5,"prereq":["诊断洞察"],"desc":"你是医学技法的大师。为医学检定增加+1奖励骰（总计+3）。"},{"name":"复原","rank":5,"prereq":["细致治疗"],"desc":"作为医学大师，你可以施行一种能大幅加速恢复的治疗。在你的护理下，患者每夜睡眠后恢复+4d4生命值和2d10耐久。"}]},
  {"skill":"工艺","intro":"尝试建造、修理或制造某物时，需要进行一次工艺检定。工艺技能是诸如金属加工、木工或宝石加工等工艺的分支。工艺也可以包括视觉艺术，比如绘画或用零件组装简单的机器。","adv":["精制品。 将制作的物品的品质提升1个等级。","高效利用。 在不影响品质的情况下，使用的材料或资源减少20%。","快速构建。 将工艺所需的时间缩短20%。"],"type":"学术","t1":"初学者工匠","effect":"工艺检定 +1 奖励骰；可制作劣质物品","nodes":[{"name":"初学者工匠","rank":1,"prereq":[],"desc":"为工艺检定增加+1奖励骰。你可以使用基础材料制作劣质物品（绝不会是孱弱品质）。你还可以学习初学者配方。"},{"name":"修补","rank":2,"prereq":["初学者工匠"],"desc":"你可以轻松修复工具与装备。修理护甲或武器时，在正常结果外额外恢复1d8点耐久。在你的回合，你可以使用1个行动、1个可用零件和15点活力进行紧急战场修理，恢复3d6点耐久。"},{"name":"材料感知","rank":2,"prereq":["初学者工匠"],"desc":"你可以瞬间鉴定材料品质和隐藏属性。通过一次成功的工艺检定（VS15+每品质等级 5），你可以确定原材料、可用零件和核心组件的品质等级及任何特殊特性（例如：柔韧、易碎、导电）。"},{"name":"巧匠","rank":2,"prereq":["初学者工匠"],"desc":"选择以下工艺专长之一：金属加工、木工、皮革加工与裁缝、建筑、玻璃与宝石加工，或其他相关工艺。你制作的该类物品默认为普通品质。"},{"name":"改造","rank":3,"prereq":["修补"],"desc":"你可以制作功能性的武器与护甲改造件。你可以制作武器握柄和头部的改造件，以及护甲改造件，但须习得相应的图纸。"},{"name":"专家工匠","rank":3,"prereq":["材料感知"],"desc":"你的技艺精进。你在工艺检定上获得+1奖励骰（总计+2）。你可以学习专家图纸。"},{"name":"工具联结","rank":3,"prereq":["巧匠"],"desc":"你制作了一套与你的战技协调的杰作工具包。使用你的联结工具时，在工艺检定中你的工艺奖励骰获得1点蓄势。如果丢失，可在休整期重制你的联结工具包。"},{"name":"装备调整","rank":4,"prereq":["改造"],"desc":"你可以快速拆解并重新配置武器模组。在你的回合中花费2个行动，你可以更换武器或护甲上的一个改造。你也可以安全移除模组而不损伤它们。"},{"name":"奥术调整","rank":4,"prereq":["改造"],"desc":"你的技能延伸至附魔与奥术工具。你可以安全地更换或调整魔法附魔武器或护甲上的改造。"},{"name":"杰作","rank":4,"prereq":["专家工匠"],"desc":"你在工艺中更容易取得卓越品质。当你冒险进行工艺检定，以求提升制品的质量时，你的目标VS仅增加+10，而非15。这同样也会调整制造所需的时间和成本。"},{"name":"武器制造","rank":4,"prereq":["工具联结"],"desc":"你在锻造武器方面的专长大放异彩。只要你拥有品质合适的材料与可用部件，在你专精领域打造的武器，其品质等级始终+1。"},{"name":"护甲制造","rank":4,"prereq":["工具联结"],"desc":"你制作防护装备的技艺无与伦比。若你有足够的时间与高品质材料，在你专精领域制造的护甲，其品质等级始终+1。修复你亲手制作的护甲时，恢复双倍耐久。"},{"name":"私人定制","rank":5,"prereq":["装备调整"],"desc":"你已掌握深度定制个人装备的技能。你可以为个人武器额外附加一个改造，超出它的通常限制。只有你能有效使用该武器；在他人手中，其改造将失效。"},{"name":"无瑕改装","rank":5,"prereq":["奥术调整"],"desc":"你将武器精炼为其形态的完美延伸。你可以在武器上牺牲头部/锋刃改造槽位，使其品质等级永久+1。此次重铸需要1个同等或更高品质的核心组件，并进行一次工艺检定， VS 40。"},{"name":"工匠大师","rank":5,"prereq":["杰作"],"desc":"你的战技是传奇级的。为工艺检定增添+1奖励骰（总计+3）。你可以学习大师图纸。打造的作品可以比基础材料高出一个品质等级。"},{"name":"武器护符","rank":5,"prereq":["武器制造"],"desc":"你可以将符咒绑定到你所打造的武器上。你打造的武器除了普通的插槽外，还会获得一个完整的符咒模块插槽。每把武器只能绑定一个这样的护符，并且一旦选择了该符咒，你仅能凭本天赋添加这一种符咒。这个符咒将成为你作为武器匠的标志。"},{"name":"硬化护甲","rank":5,"prereq":["护甲制造"],"desc":"你的盔甲能抵御所有形式的攻击。你制作的护甲可获得一种永久韧性特质：硬化（物理）、衬垫（刚）、防破片（爆炸）、隔热（火焰）或接地（电击）。这算作一项额外特性，而非一个模组槽位。"}]},
  {"skill":"表演","intro":"歌唱、器乐、舞蹈及表演艺术，当你想要进行某种形式的表演时，需进行表演检定。表演技能包括乐器演奏、歌唱、讲故事和分散注意。","adv":["迷人表演。 抵抗你表演的尝试会带有1点挑战。","激励之举。 鼓舞你的观众士气，使其下一次行动通过激励获得蓄势。","碾压性辱骂。 通过挫败士气增加一个额外挑战。"],"type":"人格","t1":"初学者表演家","effect":"表演检定 +1 奖励骰；掌握基础演出","nodes":[{"name":"初学者表演家","rank":1,"prereq":[],"desc":"在表演检定上增加1颗奖励骰。你掌握所有基础演出，并可学习初学者演出。"},{"name":"专精表演","rank":2,"prereq":["初学者表演家"],"desc":"你是某一特定表演形式的专家，选自以下列表。 *音乐。* 乐器、声乐、节奏。当你使用演出技法时，你可以影响范围内可听见你声音的额外一个目标。 *演讲。* 修辞、诗歌、故事讲述。当你成功通过一次表演检定时，你还可以为自己在同一回合的下一次社交或学识行动提供+1奖励骰。 *舞蹈。* 编舞、肢体表达。当你使用表演技法时，你可以将最多10尺的移动作为表演的一部分，而不中断表演。 *戏剧。* 面具、模仿、角色扮演、气场。经过至少3分钟的准备，你可以用表演来伪装自己或他人，在用于欺骗或魅惑的社交检定上获得+1奖励骰。"},{"name":"激励","rank":3,"prereq":["专精表演"],"desc":"你的增益表演效果增强。每当受你表演影响的盟友行动投骰成功时，其恢复 1d6 活力或魔力。"},{"name":"专家级表演者","rank":3,"prereq":["专精表演"],"desc":"为表演检定增加 +1 奖励骰（总计 +2）。你可以学习专家演出。"},{"name":"苛责","rank":3,"prereq":["专精表演"],"desc":"你的减益表演会持续留存。当你通过表演成功施加负面效应时，该效应额外持续 +1 轮。"},{"name":"标志性风格","rank":4,"prereq":["激励"],"desc":"你独特的表演身份闪耀夺目。选择一个你所知的初学者或专家表演。执行此表演时，你的表演检定获得+1奖励骰，且魔力消耗减少3点（最低为1）。"},{"name":"返场","rank":4,"prereq":["专家级表演者"],"desc":"你可以支付表演的魔力消耗作为维持费用，将其延续至多轮。你无需重掷你的表演检定。"},{"name":"蔑视","rank":4,"prereq":["苛责"],"desc":"你的言行比预想中更具杀伤力。当你成功进行一次减益表演时，目标在其下一个回合还会失去1个行动。"},{"name":"名家表演","rank":5,"prereq":["标志性风格"],"desc":"你的专精流派进化为世界级的天才： *音乐：* 受影响的盟友在你的演出期间首次成功通过行动检定时，还会恢复1d6点活力。 *演讲：* 受影响的盟友在其后两次社交/学识检定中获得+1奖励骰，而非一次。 *舞蹈：* 你在维持演出时，每回合可以移动至多半速。 *戏剧：* 你的伪装完美无瑕；除非有确凿证据，否则经得起推敲。"},{"name":"表演大师","rank":5,"prereq":["返场"],"desc":"为表演检定增加+1奖励骰（总计+3）。你可以学习大师级演出。"},{"name":"凋零","rank":5,"prereq":["蔑视"],"desc":"你的减益演出能摧垮灵魂。当你成功时，目标立即失去2d6点魔力，并在其每轮受你演出影响期间额外失去1d4点魔力。"}]},
  {"skill":"社交","intro":"建立友谊、展现魅力、外交辞令与欺诈之术。你可能会掷一次社交检定来说服对方信任你的善意，或将其争取到你这边。社交也包括心理学，可用于理解或治疗患有精神疾病的生物。社交技能包括魅力、欺诈和精神操纵。","adv":["超凡魅力。 增强你的魅力影响力，使互动更有利。","摄人心魄。 抵抗你的魅力或诱惑的尝试需承受1点挑战。","恶意欺瞒。 抵抗你的欺骗和操纵的尝试将承受1点挑战。"],"type":"人格","t1":"社交初学者","effect":"社交检定 +1 奖励骰","nodes":[{"name":"社交初学者","rank":1,"prereq":[],"desc":"你擅长与他人沟通和互动。在社交检定上获得+1奖励骰。"},{"name":"花言巧语","rank":2,"prereq":["社交初学者"],"desc":"你专精于谎言、诡计和欺骗。当你成功进行基于诡诈的社交检定时，你可以制造一个虚假细节（伪造的事实、误导的线索或编造的谣言），在被揭穿前视为真实。"},{"name":"感同身受","rank":2,"prereq":["社交初学者"],"desc":"你善于体察他人。在进行社交互动时，你可以要求GM揭示你所面对生物的一个隐藏情绪状态。此外，当你援助盟友时，受你鼓励影响的盟友在其下一次行动上获得+1奖励骰。"},{"name":"声色俱厉","rank":2,"prereq":["社交初学者"],"desc":"你擅长利用恐惧和威胁。当你成功进行社交检定 VS 目标的决心时，你可以恐吓一个生物，迫使目标在本次遭遇余下时间内陷入焦虑状态。"},{"name":"色令智昏","rank":3,"prereq":["花言巧语"],"desc":"你在诱惑与引诱方面的技艺无人能及。当你对一名易被勾引或沉迷欲望的目标进行欺骗检定并成功时，你在接下来对其进行社交或诡计检定时获得1点免费蓄势。"},{"name":"社交专家","rank":3,"prereq":["感同身受"],"desc":"你的社交风度与能力得到提升。在社交检定上增加 +1 奖励骰（总共 +2）。"},{"name":"发号施令","rank":3,"prereq":["声色俱厉"],"desc":"你展现出职权。通过暴力威胁，你可以迫使一个与你语言互通的生物在其回合内执行1个非攻击性行动。目标有权进行一次抵抗反应，对抗你的威胁（恐吓）检定，尤其是当他们并不完全信服抗命的后果时。"},{"name":"蛊惑人心","rank":4,"prereq":["色令智昏"],"desc":"你的谎言掷地有声。你能编织可怕的欺骗，致使一个生物行为无常、难以预料。选择一个能听见并理解你的生物。社交检定成功时，你可以以一种完全令人信服的方式说出一句简单的谎言。这个谎言不能完全违背现实，比如天空是绿色的或者他们是条狗，但更阴险的谎言是可能的。比如他们的朋友和盟友正在利用他们，他们是天选英雄，或者你比任何人都关心他们。除非目标针对你的诡诈检定成功进行了一次抵抗反应，否则他们会相信你操纵性的谎言并照此行事。这并非一个快速的过程，需要1d4回合的互动和欺骗，但极其有效。"},{"name":"人情达练","rank":4,"prereq":["社交专家"],"desc":"你对他人有深刻的洞察力。将你的共情值增加+8。","resource":{"emp":8}},{"name":"魂飞魄散","rank":4,"prereq":["发号施令"],"desc":"作为一个行动，你可以散发一种令人恐惧的意图气场。你的灵光延伸至30尺内所有能看见你的生物。范围内的所有生物均可进行一次抵抗反应，对抗你的威胁（威吓）检定减10。否则，每个生物都会陷入惊骇，因恐惧而麻痹，直至其下个回合结束。"},{"name":"幕后牵丝","rank":5,"prereq":["蛊惑人心"],"desc":"你的操控天衣无缝。一旦你成功使用蛊惑人心操控一个生物，在接下来每1个共情奖励骰1小时的时间内，你可以用一个行动对其下达命令，无需检定。"},{"name":"社交大师","rank":5,"prereq":["人情达练"],"desc":"你的魅力势不可挡。在社交检定上增加+1奖励骰（总计+3）。"},{"name":"望而生畏","rank":5,"prereq":["魂飞魄散"],"desc":"你的存在令人窒息。作为一个行动，你可以释放一次恐惧展示：范围内的所有敌人必须进行一次 抵抗 反应 VS 你的 社交 检定。失败时，他们陷入 恍惚 1 回合，且对你或你的盟友感到 恐惧。"}]},
  {"skill":"运动","intro":"奔跑、跳跃、游泳和攀爬，你可能会被要求进行 运动 检定以完成许多身体活动。运动技能包括高级平衡、攀爬、翻滚和游泳。","adv":["力量激增。 当你为举重、跳跃或冲刺进行 运动 检定时，你的有效力量值或速度值增加5点。","不竭强化。 进行一次运动检定后，恢复1d6点活力。"],"type":"体能","t1":"运动初学者","effect":"运动检定 +1 奖励骰","nodes":[{"name":"运动初学者","rank":1,"prereq":[],"desc":"在所有运动行动和攻击掷骰（冲刺、攀爬、跳跃、游泳、跳马）上添加+1奖励骰。"},{"name":"呼吸控制","rank":2,"prereq":["运动初学者"],"desc":"经过1分钟的准备，你可以屏息相当于你耐力属性值一半的分钟数。在此之后的每一分钟，你可以继续屏息，但每延长一分钟消耗15点活力。屏息期间，你无法恢复活力。"},{"name":"冲刺","rank":2,"prereq":["运动初学者"],"desc":"当你冲刺时，你可以以15点活力为代价，在1分钟内移动两倍于你通常速度值的距离。"},{"name":"攀升","rank":2,"prereq":["运动初学者"],"desc":"攀爬时，你可以以正常移动速度攀爬（而非以你速度的一半），但每回合消耗15点活力。以这种速度攀爬时，你无法恢复活力。"},{"name":"拖运","rank":3,"prereq":["呼吸控制"],"desc":"你已习惯于在负重时移动与行动。在陷入超载状态之前，你可以额外携带力量 ×5 磅的物品，超出你的举重值。"},{"name":"专家运动","rank":3,"prereq":["冲刺"],"desc":"你已建立起显著的平衡与耐力。你在运动检定上获得+1奖励骰（总计+2）。"},{"name":"跑酷","rank":3,"prereq":["攀升"],"desc":"在困难地形上移动时，你可以每分钟消耗10点活力，以保持全速移动。在进行跑酷移动时，你无法恢复活力。通过一次运动检定 VS 20，你可以将坠落伤害减半。"},{"name":"充沛速度","rank":4,"prereq":["拖运"],"desc":"你的最高速度与灵敏性得到强化。你的速度值+8。","resource":{"spd":8}},{"name":"充沛耐力","rank":4,"prereq":["拖运"],"desc":"你身体的耐力得到提升。耐力值 +8。","resource":{"sta":8}},{"name":"不竭活力","rank":4,"prereq":["专家运动"],"desc":"你每有1级经验等级，便额外获得+4点活力。此效果从你学习此天赋时追溯生效。例如，若你在8级时学习此天赋，会立即获得64点活力。"},{"name":"充沛敏捷","rank":4,"prereq":["跑酷"],"desc":"你的平衡、协调和反射能力得到加深。敏捷值 +8。","resource":{"agi":8}},{"name":"充沛力量","rank":4,"prereq":["跑酷"],"desc":"你的爆发力和负重能力提升。你的力量值+8。","resource":{"str":8}},{"name":"闪现步法","rank":5,"prereq":["充沛速度"],"desc":"你移动之快，令人眼花缭乱。每场景一次，通过消耗30点活力，你可以以一个行动瞬间移动至多你速度属性值×5尺的距离，每回合至多一次。"},{"name":"百折不挠","rank":5,"prereq":["充沛耐力"],"desc":"你的不竭无穷无尽。当你因一次攻击或侵袭导致生命值降至0时，如果你拥有30点活力，你可以消耗它，改为将生命值降至1点。使用此能力后，你必须完成一次完整休息才能再次使用它。每晚休息结束时，若你带有疲劳状态，则自动恢复1级疲劳。"},{"name":"运动大师","rank":5,"prereq":["不竭活力"],"desc":"你是一名顶尖的运动员。为你的运动检定添加1颗奖励骰，总计+3。"},{"name":"行动自如","rank":5,"prereq":["充沛敏捷"],"desc":"你拥有近乎完美的穿行于环境中的能力。当你在冲刺时，你可以进行跳跃、沿墙奔跑，甚至攀爬垂直表面，作为你移动行动的一部分，只要总覆盖距离在你的移动范围内。"},{"name":"强力举重","rank":5,"prereq":["充沛力量"],"desc":"以一个行动，你可以唤起不可思议的超人力量。该专长消耗30点活力，但持续一回合，你可以硬拉起至多为你举重值八倍的重量。"}]},
  {"skill":"巧手","intro":"涉及灵巧双手、非法入侵和魔术戏法时，你会被要求进行巧手检定以开锁或暗中行窃，以及闯入安全系统","adv":["快手。 减少撬锁、解除陷阱或偷取物品所需的时间，减少1个行动。","幽灵。 作为巧手行动的一部分，进行一次潜行检定。","放置。 使用巧手手法在不被目标察觉的情况下将某物安放于其身上。"],"type":"体能","t1":"初学者巧手","effect":"巧手检定 +1 奖励骰；撬锁按装置品质","nodes":[{"name":"初学者巧手","rank":1,"prereq":[],"desc":"你对巧手与锁的结构机制有所了解。所有巧手行动检定（撬锁、巧手手法、解除装置、魔术戏法）获得+1奖励骰。撬锁或解除陷阱所需的VS与行动取决于该装置的品质： | 装置品质 | VS | 行动 | | :--: | :-: | :--: | | 微不足道 | 10 | 2 | | 弱小 | 15 | 3 | | 普通 | 20 | 3 | | 英雄 | 35 | 4 | | 史诗 | 55 | 4 | | 传奇 | 75 | 5 | | 神话 | 120 | 5 | | 超凡 | 170 | 6 |"},{"name":"陷阱专家","rank":2,"prereq":["初学者巧手"],"desc":"你对陷阱很有心得，无论是解除还是设置。巧手检定成功时，你可以解除陷阱而不触发它们。此外，只要有2个可用零件，你可以在1分钟内造出一个简易陷阱（套索、铁蒺藜区、噪音发生器）。"},{"name":"撞匙开锁","rank":2,"prereq":["初学者巧手"],"desc":"你精通于破解锁具与束缚。你可以在没有撬锁工具的情况下，通过消耗1个可用零件尝试撬锁，这会破坏锁，但将使撬锁时间减少1个行动。然而，撬锁的VS增加5。"},{"name":"探云妙手","rank":2,"prereq":["初学者巧手"],"desc":"你的手快过视线。在战斗外与一个人互动时，你可以用巧手检定 VS 目标的物防，若成功，尝试从对方身上或口袋里移除物品，比如珠宝、钱包或腰包。对方甚至可以正对着你看。"},{"name":"破袭者","rank":3,"prereq":["陷阱专家"],"desc":"你可以在4回合内用2个可用部件和1个核心组件制作普通攻击陷阱，造成3d8伤害，或用2个行动设置预先制作好的陷阱。当你成功解除一个陷阱时，你可以将其拆解为零件，或在身后重新设置它。"},{"name":"巧手专家","rank":3,"prereq":["撞匙开锁"],"desc":"你开锁只花费正常时间的一半。涉及锁的巧手检定获得+1奖励骰（总计+2）。"},{"name":"误导","rank":3,"prereq":["探云妙手"],"desc":"以一个行动，你可以进行一次巧手检定对抗30，以迷惑和分散旁观者的注意力，使对你进行的察觉检定承受1点挑战惩罚，持续2回合。"},{"name":"慎密陷阱师","rank":4,"prereq":["破袭者"],"desc":"你已练就轻功步法，并对陷阱触发机关有天生的规避本能。你在任何试图规避或发现陷阱而不触发机关的检定中，均可加上你的巧手奖励骰。这包括高科技侦测装置以及原始陷阱。"},{"name":"潜入","rank":4,"prereq":["巧手专家"],"desc":"你擅长渗透。当你成功进行涉及锁、魔法屏障或屏障的巧手检定时，你也可将行动消耗减半（可与 撞匙开锁 叠加）。此外，你可以尝试绕开魔法或奥术锁。"},{"name":"偷窃","rank":4,"prereq":["误导"],"desc":"每回合至多一次，当你的一次轻武器或徒手攻击检定成功时，你可以改为偷窃一件穿戴或主动持有的事物（如武器、钥匙甚至专注）。"},{"name":"破袭大师","rank":5,"prereq":["慎密陷阱师"],"desc":"每回合一次，你可以仅用一半的行动消耗迅速解除或重置一个陷阱、机关或装置。你还可以在陷阱的机关上设置诡雷，使其在被解除、篡改或收集时触发。"},{"name":"陷阱大师","rank":5,"prereq":["慎密陷阱师"],"desc":"你可以在移动中以一个免费的行动解除或设置陷阱，无需减速。你还可以携带1个“预制陷阱”，能以1个行动部署。"},{"name":"诡术大师","rank":5,"prereq":["潜入"],"desc":"你精通精妙的骗术。你的巧手检定总计获得+3奖励骰。每回合一次，你可以自动绕开任何劣质或孱弱品质的锁或屏障。"},{"name":"幻术师","rank":5,"prereq":["偷窃"],"desc":"使用巧手时，你可以制造虚假的感官“暗示”（声音、闪光、手势）。每回合一次，你可以迫使10尺内所有注视你的生物进行一次察觉检定VS你的巧手掷骰，否则被分散注意力，将你视为隐藏状态直到你的下一回合。你还可以尝试拿起、放置或以其他方式让中型物体……以及生物消失。"},{"name":"幻影之手","rank":5,"prereq":["偷窃"],"desc":"你的双手似乎以超自然的方式移动。每回合一次，你可以在远程（至多10尺）表演一次手上功夫戏法。这允许你不直接接触地窃取、放置或操控小物件。"}]},
  {"skill":"潜行","intro":"一种保持不被看见、不被听闻、不被怀疑的技艺。潜行是盗贼、刺客、斥侯和密探的技能，是任何需要无声移动、暗中攻击或消失于阴影中的人的技能。一项潜行检定涵盖躲藏、不被发现地跟踪某人、潜入有物防的区域、从隐蔽处发动攻击，或在众目睽睽下掩饰自身存在。 **特殊：** 暗中移动。一次成功的潜行检定可使你以通常移动速度的1/4移动，但会安静且不被看到。","adv":["迅捷移动。 潜行时以正常速度的一半移动。","突袭。 当你从潜行中发动攻击时，为你的武器攻击奖励骰增加+1蓄势。","拟态。 融入环境或社交场合；使你的出现和消失不被人记住。"],"type":"体能","t1":"潜行初学者","effect":"潜行检定 +1 奖励骰","nodes":[{"name":"潜行初学者","rank":1,"prereq":[],"desc":"你已练习在不被发现和听到的情况下移动。在所有潜行检定（躲藏、尾随、突袭）上增加+1奖励骰。"},{"name":"落步无声","rank":2,"prereq":["潜行初学者"],"desc":"你的步法经过无声训练。你可以以一半全速度移动，而不会给你的潜行检定增加惩罚。若你以四分之一速度移动，则保持隐藏所需的VS减少5。"},{"name":"偷袭","rank":3,"prereq":["落步无声"],"desc":"你擅长发动突然袭击。如果你成功潜行接近一个生物，你可以在掷先攻前发动一次极其致命的突袭攻击。若此攻击命中，你获得+1奖励骰加值到伤害上。"},{"name":"潜行专家","rank":3,"prereq":["落步无声"],"desc":"你擅长隐匿。你的潜行检定获得+1奖励骰，总计+2。此外，你可以躲在比正常更小的掩护后（齐腰高、狭窄阴影）。"},{"name":"鬼影","rank":3,"prereq":["落步无声"],"desc":"你融入空间的流动中。只要你模仿附近的人（工人、守卫、旅人）的动作，你可以尝试一次潜行检定以穿过被公开观察的空间而不引起怀疑。"},{"name":"死亡标记","rank":4,"prereq":["偷袭"],"desc":"以一个行动，你可以消耗15点活力来标记视野内的一名目标。本回合结束前，你从潜行状态下对该目标发动的首次攻击自动获得+2伤害骰。"},{"name":"暗影遮蔽","rank":4,"prereq":["潜行专家"],"desc":"你可以利用环境伪装自己。准备1分钟后，你在此区域的潜行检定获得+2奖励骰，直到你离开超过60尺。当你处于躲藏状态时，你获得部分掩护。"},{"name":"瞒天过海","rank":4,"prereq":["鬼影"],"desc":"当你与一群（盟友、平民或敌人）一起移动时，你可以将你的隐蔽效果延伸至一名相邻盟友。你们两人视为一个单位进行潜行检定，取较高的掷骰结果。"},{"name":"暴烈之影","rank":5,"prereq":["死亡标记"],"desc":"每回合一次，当你通过潜行击杀或使一个目标丧失行动能力时，你可以立即尝试另一次潜行检定作为自由行动。成功时，你保持隐蔽，并可连锁进行另一次突袭。 滑流。尾随其他车辆时，你的速度提高10%，且无额外燃料消耗。 过载驾驶。消耗15点活力，使车辆的速度或机动性提高1级，持续1d4轮。"},{"name":"潜行大师","rank":5,"prereq":["暗影遮蔽"],"desc":"你是阴影与潜行的大师。你所有的潜行检定获得+1奖励骰，总计+3。"},{"name":"无形观察者","rank":5,"prereq":["瞒天过海"],"desc":"你能在有守卫的区域中穿行，仿佛隐形一般。你在进行潜行检定时，可以消耗20点活力，使自己在1d4分钟内不会被普通感官侦测到。在此期间，只有精密的魔法或科技侦测手段才可能发现你。"}]},
  {"skill":"驾驶","intro":"","adv":["回避行动。 一回合内，你的载具物防+5。"],"type":"体能","t1":"驾驶初学者","effect":"驾驶检定 +1 奖励骰；可操控常见载具","nodes":[{"name":"驾驶初学者","rank":1,"prereq":[],"desc":"所有驾驶检定（机动、旅行、基础战斗驾驶）获得+1奖励骰。你可以操控所处环境中的常见载具（汽车、船只、滑翔机、自行车等）。"},{"name":"载具专精","rank":2,"prereq":["驾驶初学者"],"desc":"选择一种你能够熟练驾驭的载具类型（汽车、飞行器、航天器、强力装甲、机甲等）。当你指挥所选类型的载具时，你可以让载具做出反应行动（如防御），并利用载具创造破绽。你可以多次选择此项天赋，每次选择一种新的载具类型。"},{"name":"王牌驾驶员","rank":3,"prereq":["载具专精"],"desc":"你可以将载具的机动性推向绝对极限。成功通过一次难度VS 25的驾驶检定，并消耗10点活力，你可以执行多种王牌机动，包括： 过载驾驶。 将你的载具推至极限，最大速度提高1/4，持续1分钟。 强力漂移。你可以忽略大多数由光滑表面或湍流/喷射尾流造成的困难地形，持续1分钟。 J型转弯。以1个行动，你完成一次完整的180度调头。 尾流滑行。 你借助前方载具的尾流，从而可以快速超越，或从能见度中消失。"},{"name":"专家驾驶","rank":3,"prereq":["载具专精"],"desc":"你的驾驶检定获得+1奖励骰（合计+2）。你可以操作你专精类型的稀有载具（坦克、战斗机、护卫舰、外骨骼）。"},{"name":"战斗机动","rank":3,"prereq":["载具专精"],"desc":"使用车载武器时，你可以应用战斗技能天赋（攻击奖励骰、瞄准技巧）。此外，当你指挥时，载具的物防增加你的速度奖励骰数，即，如果你的速度为20，你的载具物防增加+2。"},{"name":"载具爆发","rank":4,"prereq":["王牌驾驶员"],"desc":"你可以消耗10点活力，忽略一次通常会减慢或停滞你载具的地形或大气危害。持续1回合，你的载具最大速度翻倍。"},{"name":"认证精英","rank":4,"prereq":["专家驾驶"],"desc":"有了这项天赋，你可以驾驶你专业领域中标记为精英级别的载具，例如赛车、喷气式战斗机、战列舰、指挥航母、原型机甲。"},{"name":"战斗指令","rank":4,"prereq":["战斗机动"],"desc":"当驾驶一艘载有盟友的载具时，在你的回合，你可以作为一个行动来协调他们的攻击，并给予一名盟友的下一次攻击或机动掷骰+1奖励骰。"},{"name":"幻影漂移","rank":5,"prereq":["载具爆发"],"desc":"每回合一次，你可以作为反应消耗20点活力，通过执行一个不可能的行动来躲避一次针对你载具的攻击，将你的驾驶奖励骰加到你防御掷骰的防御奖励骰上。"},{"name":"幽灵司机","rank":5,"prereq":["载具爆发"],"desc":"你可以在战斗或旅行中隐藏你载具的移动。每回合一次，你可以进行一次驾驶检定，与敌人的传感器/察觉对抗；成功时，你的载具被视为隐藏1d4回合。"},{"name":"大师驾驶","rank":5,"prereq":["认证精英"],"desc":"你是一位传奇驾驶员。所有驾驶检定获得+1奖励骰（总计+3）。每回合一次，你可以宣布一个“招牌机动”（例如王牌机动、死亡螺旋、彗星俯冲、零重力旋转），除非被同样传奇的对手直接反制，否则自动成功。"},{"name":"加力燃烧","rank":5,"prereq":["战斗指令"],"desc":"消耗1个可用零件，将车载武器推向安全极限之外。下一次攻击时，武器的伤害骰等级+1，但武器承受2d6耐久损伤。"},{"name":"死亡之雨","rank":5,"prereq":["战斗指令"],"desc":"驾驶时，你可以将你的载具用作武器。这远超受控碰撞或冲撞；你的载具受到微不足道的伤害，但你根据载具的品质和尺寸造成若干伤害骰，例如一辆普通汽车造成d8，而一辆劣质摩托车则造成d6。骰数基于尺寸： | 尺寸等级 | 伤害骰 | | --- | --- | | 微型 | 1 | | 小型 | 3 | | 中型 | 6 | | 大型 | 12 | | 巨型 | 24 | | 超巨型 | 50 | | 极巨型 | 100 |"},]},
  {"skill":"察觉","intro":"此技能树涵盖感知、侦测和直觉。你可能需要进行一次察觉检定来发现你被人跟踪、注意到环境中的线索，或直觉地判断他人在说谎。察觉技能包括注意事物、调查和危险感知。","adv":["敏锐调查。 从你的调查中获得一条额外的相关信息。","隐藏侦测。 注意到隐藏或模糊的细节，面对隐藏敌人时的挑战惩罚减少1点。","敏锐感知。 将从观察或调查中获得的信息质量提升1级。"],"type":"探索","t1":"察觉初学者","effect":"察觉检定 +1 奖励骰","nodes":[{"name":"察觉初学者","rank":1,"prereq":[],"desc":"你比大多数人更快地注意到细微的矛盾、表面线索和直接威胁。在察觉检定上增加 +1 奖励骰。"},{"name":"调查员","rank":2,"prereq":["察觉初学者"],"desc":"你知道如何追踪线索。当你成功通过一次察觉检定时，你可以生成1条线索，为你或一名盟友的下一次相关调查或学识掷骰提供+1奖励骰。"},{"name":"态势察觉","rank":2,"prereq":["察觉初学者"],"desc":"你经过训练，能持续留意周围环境。如果你能看到威胁，就不会被突袭；只有隐藏或远处的敌人才能成功突袭你。"},{"name":"危险感知","rank":2,"prereq":["察觉初学者"],"desc":"你的潜意识会提醒你危险来临。如果你受到突袭影响，你可以进行一次察觉检定，对抗攻击者的最高先攻值。如果你成功，你就不会处于被突袭状态。"},{"name":"模式识别","rank":3,"prereq":["调查员"],"desc":"当你遇到多条线索、矛盾之处或踪迹时，例如进行工艺检定来判断结构稳定性、进行轻武器检定来评估一把刀刃的品质和工艺、或是进行学识检定来验证一份手稿的真伪，你可以将它们联系起来形成一个推论。每个推论为你提供 +1 奖励骰，用于一连串相关的技能检定，最多 +3。你可以保留等同于你记忆奖励骰数量的推论，并可以在一次短休期间更改一个推论。"},{"name":"专家级察觉","rank":3,"prereq":["态势察觉"],"desc":"你对周围环境有敏锐的感知。你为所有察觉检定增加 +1 奖励骰（总计 +2）。"},{"name":"第六感","rank":3,"prereq":["危险感知"],"desc":"你已发展出超自然的预知能力。你不会被突袭，并且从背后攻击你不会给攻击者带来任何优势。最后，你可以对未曾察觉的攻击做出防御反应。"},{"name":"法务洞察","rank":4,"prereq":["模式识别"],"desc":"在休整期，你可以分析证据以“锁定”一条线索。此永久洞察在再次遭遇相同类型的犯罪、实体或现象时，为察觉、学识和科学检定提供+1奖励骰。你可以保留等同于你记忆奖励骰数量的线索。每次完成休息，你可以用一个线索换取另一个，或完全忘记一个线索。"},{"name":"战场察觉","rank":4,"prereq":["专家级察觉"],"desc":"你的察觉延伸至盟友。作为一个反应，你也可以消耗5点活力，与能听到你的盟友交换先攻顺序。"},{"name":"预感","rank":4,"prereq":["第六感"],"desc":"每天开始时，进行一次察觉检定 VS 40。成功时，获得1个预感标记。你可花费此标记，在当天（非休整期）进行的行动察觉检定中自动成功。"},{"name":"大师侦探","rank":5,"prereq":["法务洞察"],"desc":"每场游戏一次，你可以向GM询问一个关于未解之谜、犯罪或模式的问题。答案必须真实有用，尽管不一定完整。"},{"name":"大师察觉","rank":5,"prereq":["战场察觉"],"desc":"敏锐的注意力和洞察力让你几乎无所遗漏。在所有察觉检定上增加+1奖励骰（总计+3）。"},{"name":"预兆","rank":5,"prereq":["预感"],"desc":"当视线内的一名盟友被一次使其受伤的攻击或侵袭击中时，你可以用反应行动花费20点活力来“重置”那一刻——大声警告，或在他们相邻时甚至飞身挡在路前。该盟友可以重投其防御或抵抗检定并获得+1奖励骰，或者你可以拦截这次攻击，但你无法进行防御或抵抗检定。一旦使用了此预兆，你必须完成一次完整的休息后才能再次使用它。"}]},
  {"skill":"驯兽","intro":"不仅是畜牧与骑马，实际上与动物的任何互动都由驯兽涵盖。当你试图在战斗中控制坐骑或训练动物时，你将进行一次驯兽检定。驯兽技能包括骑乘动物、与动物共同训练和狩猎，以及安抚野兽。","adv":["安抚气场。 野兽在抵抗你的安抚时有1点挑战。","训练精通。 加快训练过程，所需时间减少20%。","信任羁绊。 当你命令动物伙伴时，为其行动掷骰增加1蓄势。"],"type":"探索","t1":"驯兽初学者","effect":"驯兽检定 +1 奖励骰；识别动物情绪","nodes":[{"name":"驯兽初学者","rank":1,"prereq":[],"desc":"在驯兽检定（驯服、训练、安抚、骑乘）上增加+1奖励骰。你能一眼识别动物的情绪和基本意图。"},{"name":"动物伙伴","rank":2,"prereq":["驯兽初学者"],"desc":"假以时日，你能与一只忠诚的动物建立纽带。这种生物大致相当于狼、鹰、马或类似的自然野兽。它会服从指令，根据你的先攻行动，并随你提升等级而变强。如果你的同伴死亡，经过一个月的训练后，你可以与另一只建立纽带。更多信息见装备章节中的坐骑与同伴。"},{"name":"狩猎伙伴","rank":3,"prereq":["动物伙伴"],"desc":"你训练动物伙伴掌握协同作战技巧。每回合一次，当你打击一名敌人时，若你的伙伴相邻于该目标，则可对其发动一次免费攻击。"},{"name":"驯兽专家","rank":3,"prereq":["动物伙伴"],"desc":"你能直觉感知动物的需求与感受。你在驯兽检定上获得+1奖励骰（总计+2）。"},{"name":"骑手","rank":3,"prereq":["动物伙伴"],"desc":"你专精于骑乘战斗与旅行。骑乘时，你在运动、防御、重武器和轻武器检定上获得+1奖励骰。你的坐骑的速度增加5尺，数值等于你的驯兽技能奖励骰数。"},{"name":"集群战术","rank":4,"prereq":["狩猎伙伴"],"desc":"当你和你的同伴攻击同一目标时，同伴的攻击视为夹击。此外，当你的同伴击倒一名敌人时，你恢复1d6活力。"},{"name":"兽语者","rank":4,"prereq":["驯兽专家"],"desc":"面对一头具有攻击性或受惊的动物时，你可以尝试安抚它，让野兽相信你并非威胁或猎物。除普通的驯兽检定外，一旦动物被安抚，它便会表现得正常，且可能愿意接近或接受处置。要安抚一头野兽，你需要进行一次驯兽检定，对抗该生物的决心。此能力对魔法生物无效。"},{"name":"骑乘战斗","rank":4,"prereq":["骑手"],"desc":"你能将坐骑的力量转化为你武器的力量。每回合一次，当你骑在受过战斗训练的动物背上使用近战武器攻击时，你拥有显著优势，为你的所有伤害奖励骰增加1蓄势。"},{"name":"猎手羁绊","rank":5,"prereq":["集群战术"],"desc":"你与你的伙伴是天衣无缝的掠食者。每回合一次，当你的伙伴击中一个目标时，它会制造一个破绽，你可以选择抓住这个机会，对同一敌人发动一次攻击。"},{"name":"猎鹰之眼","rank":5,"prereq":["集群战术"],"desc":"你可以让你的动物升空（只要它有办法攀升）以提供高空监视。激活时，你的察觉检定获得+1奖励骰，并且当以你的伙伴标记的目标敌人为目标时，可以忽略掩体惩罚。"},{"name":"驯兽大师","rank":5,"prereq":["兽语者"],"desc":"为所有驯兽检定增加+1奖励骰（总计+3）。你可以拥有最多2只受过训练的同伴（但每回合只能不受惩罚地指挥其中一只参与战斗）。"},{"name":"骑士","rank":5,"prereq":["骑乘战斗"],"desc":"你与你的坐骑协同作战，如同一体。骑乘时，你的近战攻击获得+1武器伤害骰，并且可以使用冲锋行动践踏敌人（迫使进行运动 VS 25，否则将其击倒）。 你可以同时指挥至多3个友方坐骑或战兽。每场景一次，你可以用一个驯兽投骰 VS 40来激励它们，使它们的所有攻击检定获得+1奖励骰，持续2回合。"},{"name":"万兽之王","rank":5,"prereq":["骑乘战斗"],"desc":"你可以同时命令最多3只友方坐骑或战兽，每场景一次，你可以通过一次 VS 40 的驯兽检定鼓舞它们，使它们在两回合内的所有攻击上获得 +1 奖励骰。"}]},
  {"skill":"生存","intro":"涉及狩猎、钓鱼、定向越野和木工技能的求生技能，你可以进行一次生存检定，以便在野外寻找食物或淡水、生火或追踪动物。生存技能包括定向越野、木工技能以及狩猎和追踪。","adv":["巧妙觅食。 狩猎和觅食将额外获得一天的口粮。","高级追踪。 提高追踪信息的准确性和细节。","耐用庇护所。 你制作的工具和庇护所品质高一阶。"],"type":"探索","t1":"生存初学者","effect":"生存检定 +1 奖励骰；总能找到食物和水","nodes":[{"name":"生存初学者","rank":1,"prereq":[],"desc":"所有生存检定（觅食、导航、追踪、天气预测）增加+1奖励骰。在任何可居住的生物群落中，你总能找到足以维持自己的食物和水。"},{"name":"足智多材","rank":2,"prereq":["生存初学者"],"desc":"你可以从自然或被杀死的野兽身上获取可用材料。在一次VS 30的生存检定中，你可以收集被杀生物的部位；获得1d4个可用部件，或一个与该生物品质相匹配的核心组件（一般为普通、英雄或史诗）。"},{"name":"定向越野","rank":3,"prereq":["足智多材"],"desc":"你的地图、直觉和天文感知很少出错。在进行导航和定向越野的生存检定时，你可以重投任何出现的1，但必须接受第二次投掷的结果，即使它仍然是1。在旅行途中，除非受到魔法影响，否则你的队伍不会迷路。"},{"name":"生存专家","rank":3,"prereq":["足智多材"],"desc":"你能轻松地以天地为生。生存检定再增加+1奖励骰（总计+2）。通过一次短休，你可以在除最干旱条件外的所有情况下，为最多4名盟友准备食物和水。"},{"name":"狩猎与追踪","rank":3,"prereq":["足智多材"],"desc":"你是一名熟练的猎人。当你追捕猎物时，在一次生存检定 VS 20（或潜行对抗检定）中，你能追踪足迹，并可立即判断其新鲜程度（精确到1小时内）。"},{"name":"躲避追捕","rank":4,"prereq":["定向越野"],"desc":"你懂得如何利用地形隐匿行踪。在你带领下旅行时，你的队伍在潜行检定中获得+1奖励骰。每天一次，你可以迫使追踪者进行察觉VS你的生存检定，若其失败，其失去你的踪迹。"},{"name":"披荆斩棘","rank":4,"prereq":["定向越野"],"desc":"你可以在荒野中开辟道路。在开辟新路线时，你团队的陆地旅行速度提高1/3。你可以建立一条半永久路线，他人可以免费再次使用一次，且你可以在完成一次完整休息后恢复此能力。"},{"name":"猎手体魄","rank":4,"prereq":["生存专家"],"desc":"你拥有训练有素的捕食者般的体格。将你的敏捷和耐力属性值各提升+4。","resource":{"agi":4,"sta":4}},{"name":"潜行追踪","rank":4,"prereq":["狩猎与追踪"],"desc":"你像捕食者一样移动。在自然地形中进行潜行检定时获得+1奖励骰。若你在荒野中从藏匿状态发动攻击，你的首次攻击额外增加+1伤害骰。"},{"name":"设置陷阱","rank":4,"prereq":["狩猎与追踪"],"desc":"你精通圈套、陷坑和落石陷阱。你可以在荒野环境中使用巧手无需材料制作和设置陷阱。若你拥有材料，在自然环境中你的陷阱等级提升1级。"},{"name":"销声匿迹","rank":5,"prereq":["躲避追捕"],"desc":"你对地形的了解使你能够不留痕迹地消失。在陆路旅行时，你可以将你的生存奖励骰加至潜行奖励骰，以决定任何追踪者的察觉检定的VS。"},{"name":"开拓者","rank":5,"prereq":["披荆斩棘"],"desc":"只要你身处同一现实并可见主要天体，你就不会迷路。在地下或迷宫中，你总能感知到北方。"},{"name":"生存大师","rank":5,"prereq":["猎手体魄"],"desc":"你在荒野中坚不可摧。所有生存检定额外+1奖励骰（总计+3）。在荒野中休息时，你恢复的生命值和魔力翻倍。"},{"name":"掠食打击","rank":5,"prereq":["潜行追踪"],"desc":"在自然地形中从潜行发起攻击时，你的刚具有毁灭性。增加+2武器伤害骰，并对目标施加恍惚状态，直至其下个回合结束。 你可以以惊人的效率设置多个陷阱。在自然环境中时，你可以将设置陷阱的时间减半（见巧手），最少为1个行动。你设置的陷阱也进行了很好的伪装，使注意到它们的VS增加1"},{"name":"捕兽大师","rank":5,"prereq":["设置陷阱"],"desc":""}]},
  {"skill":"奥秘","intro":"使用此技能来施展魔法战技、念诵咒语和祷文、鉴定魔法古代遗物、理解灵性能量，或执行仪式以触及塑造现实的不可见力量。奥秘是对超自然现象的研究与实践：魔法战技、对爱德丝的祈祷、灵性契约，或魔女眷属的古老巫术。掷奥秘来施展咒语、解读魔法文字、圣化遗物，或与灵体沟通。 **特殊：** 魔法战技攻击。除非另有说明，当你使用魔法战技进行攻击或侵袭时，你掷一次奥秘检定。","adv":["增强护符。 将你的魔法圣物、护符和魔法书的品质等级提升1级。","仪式强化。 将一项仪式魔法的效果提升1级，使其更加强力。","灵体沟通。 从精魂、恶魔和神祇处获得的信息额外增加1条。"],"type":"秘术","t1":"符文初学者","effect":"奥秘检定 +1 奖励骰（施法、辨识古代魔法、使用遗物）","nodes":[{"name":"符文初学者","rank":1,"prereq":[],"desc":"当你进行奥秘检定以施展大多数魔法战技、辨识或理解古代魔法，或利用古代遗物时，你的奥秘检定获得+1奖励骰。这包括魔女眷属的力量以及奇术导力魔法。"},{"name":"冥想","rank":2,"prereq":["符文初学者"],"desc":"你擅长深奥的、恢复性的冥想。在你进行修养冥想时，每分钟恢复2点魔力，最多达到你灵性值的两倍。"},{"name":"古代魔法","rank":3,"prereq":["冥想"],"desc":"拥有此天赋，你熟知黑暗时代的魔法，并能利用这些知识高效地赋予古代遗物力量。你在激活和同调古代遗物的奥秘检定中获得1点蓄势。"},{"name":"符文专家","rank":3,"prereq":["冥想"],"desc":"你扩展了关于符文与奥秘技艺的知识。你在所有奥秘检定中获得+1奖励骰（总计+2）。"},{"name":"咒文咏唱","rank":3,"prereq":["冥想"],"desc":"你精通符文形式的咒文，包括魔女眷属的魔法与奇术祷言。拥有此天赋，你可以学习法术与祷言。使用奥秘（符文）作为这些能力的施法行动检定。然而，除非你有导师，否则你不会自动学会任何这些能力。"},{"name":"七耀炼成","rank":4,"prereq":["古代魔法"],"desc":"通过奥秘检定 VS 40，并消耗40魔力，你可以将单种元素的40耀晶石转化为你研究过或能实验的同元素普通结晶回路。"},{"name":"物质附魔","rank":4,"prereq":["古代魔法"],"desc":"你可以将灵魂束缚到物体中。你可以通过一次奥秘检定 VS 25 并耗费两天时间来工艺制作护符和符咒（这些装备模组详见装备章节）。"},{"name":"灵性共鸣","rank":4,"prereq":["符文专家"],"desc":"你实现了一种灵性觉醒。你的灵性属性值增加8点。","resource":{"sol":8}},{"name":"巫术魔法","rank":4,"prereq":["咒文咏唱"],"desc":"你已经知晓了巫术的秘密——那是一种无需导力器或结晶回路即可施展导力魔法的古代力量。当你发展这项天赋时，你从你至少施放过3次的导力魔法中习得1种巫术导力魔法。你现在可以通过咒语来施展此魔法。这种施展导力魔法的方式会使施法时间加倍，并消耗魔力而非导力能量点数。然而，一旦学会，无论你的导力器状态如何，你都可以施展这些导力魔法。学习新的巫术导力魔法需要训练或研究。"},{"name":"奇术","rank":4,"prereq":["咒文咏唱"],"desc":"凭借这项天赋，你加深了对献给爱德丝的符文祈祷的理解，并能呼唤她的神圣箴言。奇术的祷言与导力魔法是教会严密守护的秘密，但你仍学会了“祝福”祷言。学习新的祷言需要训练。"},{"name":"符文工艺","rank":5,"prereq":["物质附魔"],"desc":"消耗20个耀晶石和30点魔力，你可以花费20分钟将符文刻印到武器或护甲上。完成后，进行一次奥秘检定 VS 40。成功时，符文将提供以下被动效应： *武器：* +1d8伤害，属性与所用耀晶石匹配。 *护甲：* 针对与所用耀晶石匹配的属性，获得+3护甲等级。 一件物品每个高于劣质的品质等级可容纳1个符文（普通1，英雄2，史诗3）。 工艺检定失败时，符文哑火，并消耗一半材料。"},{"name":"符文大师","rank":5,"prereq":["灵性共鸣"],"desc":"你对奥秘有着无与伦比的理解。你所有的奥秘检定获得+1奖励骰（总计+3）。"},{"name":"失落魔法","rank":5,"prereq":["巫术魔法"],"desc":"你深入钻研了古老的魔法秘辛。你学会将一道失落魔法作为咒语施展，如有时间钻研，还可习得更多。"}]},
  {"skill":"导力魔法","intro":"导力魔法代表着对导力器的精通，以及精神、科技与战术战斗的融合。进行导力魔法检定以启动导力魔法、操控如法杖或战术壳等导力链接武器，或通过导力网络强化盟友。","adv":["导力延伸。 将你的导力魔法的尺寸增量提升1级，最高至XL"],"type":"秘术","t1":"施法初学者","effect":"导力魔法检定 +1 奖励骰","nodes":[{"name":"施法初学者","rank":1,"prereq":[],"desc":"你擅长快速而准确地激活导力魔法。为你所有的导力魔法检定增加+1奖励骰。"},{"name":"导力器精通","rank":2,"prereq":["施法初学者"],"desc":"你对战术性使用导力器足够熟练，能够在你的导力魔法中运用你的精神能量。将你的灵性奖励骰加到自己用导力魔法造成的伤害和治疗上。"},{"name":"高效导力器","rank":2,"prereq":["施法初学者"],"desc":"你知道如何高效地为导力器充能并进行管理。增加你的导力能量50点。"},{"name":"战斗导力器","rank":2,"prereq":["施法初学者"],"desc":"你对导力链接武器（例如魔导杖或战术壳）的熟练度有所提升。使用此类导力链接武器攻击时，你可以利用其武器特性。当持用造成元素伤害的导力链接武器时，你可以将灵性奖励骰加到伤害上。"},{"name":"导力干扰","rank":3,"prereq":["导力器精通"],"desc":"运用高级导力技法，你干扰敌人的导力器，扭转战局。花费2个行动，你制造一个压制场，使半径10尺内的所有人陷入封魔状态，持续2回合。"},{"name":"施法专家","rank":3,"prereq":["高效导力器"],"desc":"你是一名熟练的导力器使用者。为你所有的导力魔法检定添加+1奖励骰，总计+2。"},{"name":"武器链接","rank":3,"prereq":["战斗导力器"],"desc":"你可以对你使用的任何导力武器进行超载。当你在攻击检定时消耗20点导力能量，若命中，你可以为导力武器（不仅仅是链接武器）的伤害添加+1奖励骰。若未命中，能量会被浪费。"},{"name":"导力护盾","rank":4,"prereq":["导力干扰"],"desc":"当你尝试以防御反应进行格挡时，可消耗10点导力能量，令所承受的伤害额外减免等同于你「导力魔法施法」奖励骰的数值。"},{"name":"快速施法","rank":4,"prereq":["施法专家"],"desc":"你长时间的练习使你几乎能瞬间施展导力魔法。将所有导力魔法的施法时间减少1个行动，最少为1个行动。若这原本会使某个导力魔法的施法时间降至0，你可以在选择抓住破绽时施展该魔法。"},{"name":"觉醒链接","rank":4,"prereq":["武器链接"],"desc":"每回合当你使用导力链接武器攻击时，你获得1个额外的攻击行动。"},{"name":"导力器解锁","rank":5,"prereq":["导力护盾"],"desc":"你已学会绕过战术导力器的安全限制器，解锁了危险的潜力。选择以下一项导力器破解项： *双重施法。* 每回合一次，你可以用一个承受2点挑战的施法检定同时施放两个施法时间相同的导力魔法。两者正常消耗EP。 *奥术超载。* 每回合一次，你可以在单次导力魔法检定中进行1次冒险而不提升VS。 *精通回路。* 你施放的所有与你元素相性有关的导力魔法在效应上被视为品质等级提升1级。 *导力升华。* 你的导力器以完美的效率共鸣。你的最大导力能量永久增加 +100。"},{"name":"施法大师","rank":5,"prereq":["快速施法"],"desc":"你已精通战术导力器，在所有导力魔法检定上获得+1奖励骰，总奖励骰至+3。"},{"name":"协同指挥","rank":5,"prereq":["觉醒链接"],"desc":"通过协调第5/6代导力器，你的链接系统变得完美无瑕。所有与你的导力器相连的盟友，在利用你创造的破绽时，获得 +1 奖励骰。"}]},
  {"skill":"远程武器","intro":"当你试图用投掷或远程弹射武器击中目标时，需要进行远程武器检定。你可以将你的敏捷奖励骰（如果有的话）加到此掷骰中。 **特殊：** 远程伤害。你不会自动将你的STR（力量）奖励骰加到远程武器造成的伤害上。你需要一项天赋来追加此额外伤害。火器独特之处在于，若你擅长使用，你会将技能奖励骰加到伤害上，因为你不会将任何属性值的奖励骰加到火器伤害中。","adv":["伤害。 为你的伤害奖励骰增加1点蓄势。","精准射击。 瞄准护甲缝隙，忽略品质低于你武器的护甲。","弹射射击。 将射弹从表面反弹以命中，为对手的防御反应增加一个挑战（若采取的话）。"],"type":"武器","t1":"远程武器初学者","effect":"远程攻击与行动检定 +1 奖励骰；可学基础/初学者远程技法","nodes":[{"name":"远程武器初学者","rank":1,"prereq":[],"desc":"远程武器攻击和行动检定获得+1奖励骰。你可以使用基础远程武器技法，并学习初学者远程武器技法。"},{"name":"弓箭手","rank":2,"prereq":["远程武器初学者"],"desc":"当你使用拉弓或类似武器攻击时，你可以将你的力量奖励骰添加到伤害中。"},{"name":"协调射击","rank":2,"prereq":["远程武器初学者"],"desc":"你拥有更强的平衡性和精准度。你的敏捷属性值+4。","resource":{"agi":4}},{"name":"强力投掷","rank":2,"prereq":["远程武器初学者"],"desc":"当你使用投掷武器进行攻击时，你可以将你的力量奖励骰加到伤害上。"},{"name":"神射手","rank":2,"prereq":["远程武器初学者"],"desc":"当使用火器、弩或类似机械远程武器攻击时，你将技能奖励骰加到伤害上。你可以利用机械武器和火器的特性，比如爆发。"},{"name":"双箭齐发","rank":3,"prereq":["弓箭手"],"desc":"当你使用弓或类似的拉弦武器时，你可以进行一次冒险，向正常射程内的单一目标射出两支相同的箭矢。如果你命中，你造成双倍武器伤害并消耗2发弹药。"},{"name":"远程武器专家","rank":3,"prereq":["协调射击"],"desc":"当你使用远程武器进行攻击和行动检定时，你获得+1奖励骰（总计+2）。你可以学习专家远程武器技法。"},{"name":"二连投掷","rank":3,"prereq":["强力投掷"],"desc":"当你投掷具有轻巧特性的武器时，你可以进行一次冒险，向正常射程内的单一目标投掷两枚投掷物。如果你命中，你造成双倍武器伤害并消耗2发弹药。"},{"name":"狙击","rank":3,"prereq":["神射手"],"desc":"装备火器、弩或类似机械武器时，你可以将整个回合用于精确瞄准。在你的下一个回合，你用步枪进行的第一次攻击行动，其攻击检定获得+2奖励骰。"},{"name":"三箭齐发","rank":4,"prereq":["双箭齐发"],"desc":"当你使用弓或类似的拉弦武器时，你可以进行一次冒险，向正常射程内的单一目标射出三支相同的箭矢。如果你命中，你造成三倍武器伤害并消耗3发弹药。"},{"name":"快速射击","rank":4,"prereq":["双箭齐发"],"desc":"当你使用弓或相似的拉弦武器连续进行2次攻击行动或远程武器技法时，你可用该武器进行一次额外的免费基础远程攻击行动。"},{"name":"额外行动","rank":4,"prereq":["远程武器专家"],"desc":"你在你的回合中获得1个额外行动。"},{"name":"迅捷投掷","rank":4,"prereq":["二连投掷"],"desc":"你可以用副手使用投掷武器。你可以在你的回合进行一次副手投掷攻击。"},{"name":"二连速射","rank":4,"prereq":["狙击"],"desc":"使用火器、弩或类似的机械武器时，你可以快速装填或发射2发弹药，视为一次攻击掷骰。如果你命中，你造成双倍武器伤害并消耗2发弹药。将双发速射与连发武器组合使用，你便能倾泻弹雨。"},{"name":"快速装填","rank":4,"prereq":["狙击"],"desc":"装备枪械、弩或类似的机械武器时，你装填武器所需的行动消耗减少1个行动，最低可减至0。"},{"name":"贯穿射击","rank":5,"prereq":["三箭齐发"],"desc":"使用弓或类似的拉弦武器时，你可以让你的射击直接穿透一个又一个目标。在你的回合内，你的弓每有一次攻击命中并造成伤害，就会使你的下一支箭的威胁值变为4，此效果可累计。此加值在你的回合结束时消失。"},{"name":"抛射","rank":5,"prereq":["快速射击"],"desc":"使用弓或类似的拉弦武器时，你可以向上以抛物线弧线射出弹药，使射弹飞得更远。使用弧线射击，你可以攻击一个额外的极限距离类别，该距离等于你武器远距射程的2倍。弧线射击会使你的攻击掷骰承受2点挑战惩罚，但你的武器伤害获得+1奖励骰，并获得1蓄势。弧线射击使用的普通品质箭矢或弩矢将被摧毁。"},{"name":"远程武器大师","rank":5,"prereq":["额外行动"],"desc":"当你使用远程武器进行攻击和行动掷骰时，你添加+1奖励骰（总计+3）。你足够熟练，可以学习大师级远程武器技法。"},{"name":"三连投掷","rank":5,"prereq":["迅捷投掷"],"desc":"当你投掷一件具有轻巧特征的武器时，你可以进行一次冒险，向正常射程内的单个目标投出两支箭矢。若命中，你造成三倍武器伤害并消耗3发弹药。"},{"name":"快速拔取","rank":5,"prereq":["二连速射"],"desc":"当使用单手火器或类似的机械远程武器时，你可以将你的技能奖励骰加到先攻值上。"},{"name":"百步穿扬","rank":5,"prereq":["快速装填"],"desc":"当你使用狙击时，你可以瞄准处于第三个超远射程范围内的敌人，该射程等于你武器长射程的2倍。这次攻击使你的攻击检定承受2点沉重的挑战惩罚，但你的敌人无法对其使用防御反应。"}]},
  {"skill":"重武器","intro":"当你使用依靠力量和重量的大型武器进行攻击（例如双手斧和战锤）时，你将进行一次重武器检定。重武器技能包括碾碎武器、巨剑和长柄武器。","adv":["毁灭打击。 为你的伤害奖励骰增加1点蓄势。","破甲。 忽略任何品质低于你武器的护甲。","横扫攻击。 击中主要目标相邻的一个额外目标，该目标获得1点防御蓄势。"],"type":"武器","t1":"重武器初学者","effect":"重武器攻击与行动检定 +1 奖励骰；可学基础/初学者重武器技法","nodes":[{"name":"重武器初学者","rank":1,"prereq":[],"desc":"所有重武器攻击和行动检定增加+1奖励骰。你可以使用重武器的任何基本技法，并且可以学习初学者的重武器技法。"},{"name":"巨剑士","rank":2,"prereq":["重武器初学者"],"desc":"当持用任何样式的双手剑或类似武器时，你可以利用其 横扫 或 巧御 等特性。"},{"name":"撕裂打击","rank":2,"prereq":["重武器初学者"],"desc":"当使用具有冲击或横扫特性的双手斧（或任何劈砍型兵刃）攻击时，你可以运用这些武器特性。"},{"name":"不动如山","rank":2,"prereq":["重武器初学者"],"desc":"你稳固的站姿让你能不断挥击。将你的力量值提升 4 点。","resource":{"str":4}},{"name":"粉碎打击","rank":2,"prereq":["重武器初学者"],"desc":"当使用具有冲击或粉碎特性的双手锤、棒或战锤攻击时，你可以运用这些武器特性。"},{"name":"长柄武器熟练","rank":2,"prereq":["重武器初学者"],"desc":"当使用具有触及特性的矛、长刀、戟或类似长柄武器攻击时，你可以运用其特性。"},{"name":"劈砍打击","rank":3,"prereq":["巨剑士"],"desc":"当持用双手剑或类似刀剑时，你可以单手持剑进行攻击行动。"},{"name":"裂地横扫","rank":3,"prereq":["撕裂打击"],"desc":"当持用具有 横扫 特性的重斧或其他劈砍型刀剑时，你可以在攻击时进行冒险，以用你的 横扫 打击第二个相邻的敌人。"},{"name":"重武器专家","rank":3,"prereq":["不动如山"],"desc":"当你进行重武器攻击和行动检定时，你增加 +1 奖励骰（总计 +2）。"},{"name":"碾压挥击","rank":3,"prereq":["粉碎打击"],"desc":"当你用双手钝器命中时，你可以进行一次尝试，将目标击退 10 尺；若该武器拥有推挤特性，则额外再将他们击退 10 尺。如果他们撞到地形或另一生物，就会倒地。"},{"name":"弓步突刺","rank":3,"prereq":["长柄武器熟练"],"desc":"当使用长柄武器或长杖攻击时，你可以冒险，为你的攻击增加额外的 5 尺触及以进行远距离攻击。"},{"name":"强力顺劈","rank":4,"prereq":["劈砍打击"],"desc":"你能顺劈多个敌人。你可以在你的回合中用巨剑进行一次额外的横扫攻击。"},{"name":"破甲打击","rank":4,"prereq":["劈砍打击"],"desc":"当你使用大剑或具有 横扫 或 冲击 特性的类似武器进行攻击行动或武器技法时，你可以选择放弃该特性，使得你的剑在此次攻击中获得  威胁(6)。"},{"name":"撕裂冲击","rank":4,"prereq":["裂地横扫"],"desc":"摧毁并撕裂你面前的所有敌人。你的双手斧武器的冲击伤害忽略护甲等级。"},{"name":"额外行动","rank":4,"prereq":["重武器专家"],"desc":"你在你的回合中获得1个额外行动。"},{"name":"野蛮冲锋","rank":4,"prereq":["碾压挥击"],"desc":"当你使用碾压挥击时，你可以进行第二次冒险来猛击另一个相邻的敌人，造成武器伤害并将其击退 5 尺。"},{"name":"回旋打击","rank":4,"prereq":["弓步突刺"],"desc":"当你使用双头武器（如长棍或双刃矛）的反刃端进行副手攻击时，消耗仅为5点活力，且攻击掷骰和伤害掷骰仅承受1个挑战。"},{"name":"运柄成势","rank":4,"prereq":["弓步突刺"],"desc":"当你在触及范围内用长柄武器攻击时，借助杠杆作用，你可以为你的打击附加额外的力道。不论武器其他特性如何，该攻击获得额外的威胁 (6)。"},{"name":"无尽顺劈","rank":5,"prereq":["强力顺劈"],"desc":"如汹涌潮水般在敌群中前行。当你使用带有横扫特性的双手剑时，每回合可以使用该特性的次数没有限制。"},{"name":"断骨","rank":5,"prereq":["破甲打击"],"desc":"斩断一切阻碍。装备双手剑或类似武器时，你可以放弃所有其他武器特性效应，直接对生命值或完好度造成等同于你力量奖励骰两倍的伤害。"},{"name":"劈山","rank":5,"prereq":["撕裂冲击"],"desc":"当你使用粉碎挥击时，你可以消耗两个冒险，造成三倍武器伤害，而非两倍。"},{"name":"重武器大师","rank":5,"prereq":["额外行动"],"desc":"当你进行重武器攻击和行动掷骰时，你额外获得+1奖励骰（总计+3）。"},{"name":"震地击","rank":5,"prereq":["野蛮冲锋"],"desc":"每次挥击皆震裂大地。当你使用钝器类双手武器攻击未命中，或被防御时，你对目标相邻的所有敌人造成等同于你力量奖励骰数量的伤害。"},{"name":"旋风斩","rank":5,"prereq":["回旋打击"],"desc":"你已掌握了双持武器的致命优雅。当你使用双头武器的反面进行副手攻击时，你不会承受任何挑战。"},{"name":"刺穿","rank":5,"prereq":["运柄成势"],"desc":"当你使用触及武器攻击，且你的伤害奖励骰爆发时，你可以改为直接将爆发骰造成的伤害作用于生命值或完整度。"}]},
  {"skill":"轻武器","intro":"当你使用单手武器或手半武器进行近战攻击时，你进行一次轻武器检定。轻武器将力量奖励骰加至伤害。要利用武器特性，你必须熟练使用该武器。","adv":["精准打击。 为你的伤害奖励骰增加1点蓄势。","穿甲。 忽略任何品质低于你武器的护甲。","快速拔刀。 你以流畅的行动拔剑攻击。"],"type":"武器","t1":"轻武器初学者","effect":"轻武器攻击与行动检定 +1 奖励骰；可学基础/初学者轻武器技法","nodes":[{"name":"轻武器初学者","rank":1,"prereq":[],"desc":"所有轻武器攻击和行动掷骰获得+1奖励骰。你可以使用轻武器的任何基本技法，并且可以学习初学者的轻武器技法。"},{"name":"剑士","rank":2,"prereq":["轻武器初学者"],"desc":"当你使用带有两用、迅捷或巧御特性的单手刃器或类似剑的斩击武器攻击时，你可以利用这些武器特性。"},{"name":"刀术","rank":2,"prereq":["轻武器初学者"],"desc":"当你使用带有威胁、迅捷或巧御特性的匕首或类似灵巧武器攻击时，你可以利用这些武器特性。"},{"name":"平衡","rank":2,"prereq":["轻武器初学者"],"desc":"你的架势和步法无可挑剔。你的敏捷属性值+4。","resource":{"agi":4}},{"name":"残忍刚击","rank":2,"prereq":["轻武器初学者"],"desc":"当你使用单手斧、钉头锤、棍棒或锤攻击时，你可以利用诸如冲击、巧御和两用等特性。"},{"name":"双持运用","rank":2,"prereq":["轻武器初学者"],"desc":"当你副手持有带有轻型或守御特性的武器时，你可以利用该特性。"},{"name":"回旋步","rank":3,"prereq":["剑士"],"desc":"当你使用剑进行攻击或使用战斗技法时，作为攻击行动的一部分，你可以朝目标移动5尺或移动到其相邻位置。"},{"name":"近身格斗（CQC）","rank":3,"prereq":["刀术"],"desc":"当你在近战中成功进行一次匕首攻击或战斗技法时，你本回合的下一次匕首攻击获得威胁（3）。此能力每回合可使用一次。"},{"name":"轻武器专家","rank":3,"prereq":["平衡"],"desc":"当你进行轻武器攻击和行动掷骰时，你获得+1奖励骰（总计+2），并且你可以学习专家级轻武器技法。"},{"name":"碎骨击","rank":3,"prereq":["残忍刚击"],"desc":"当你用打击类武器命中时，你可以进行，改为造成双倍武器伤害。"},{"name":"双持娴熟","rank":3,"prereq":["双持运用"],"desc":"你曾练习过双持均衡的战斗方式。当你使用副手的轻武器进行副手攻击时，你的攻击和伤害奖励骰只会遭受1点挑战。"},{"name":"二连斩","rank":4,"prereq":["回旋步"],"desc":"当你使用剑或类似武器成功进行一次基础攻击后，你可以立即进行一次追加斩击。若命中，此攻击仅造成武器伤害（无奖励骰）。"},{"name":"强力一击","rank":4,"prereq":["回旋步"],"desc":"你的刚击流转着完美的精准。当你进行一次冒险来增加剑类打击的伤害时，你的攻击获得冲击特性。"},{"name":"放倒","rank":4,"prereq":["近身格斗（CQC）"],"desc":"当使用匕首成功进行一次攻击行动后，你可以用一次行动将对手击倒在地，使其倒地，除非其成功通过抵抗（力量）VS 你的敏捷值。你必须花费一次行动来使用此技巧。"},{"name":"额外行动","rank":4,"prereq":["轻武器专家"],"desc":"你在你的回合中获得1个额外行动。"},{"name":"破灭一击","rank":4,"prereq":["碎骨击"],"desc":"毫不留情地歼灭你的敌人。当你使用打击武器命中并造成伤害时，目标恍惚1回合。"},{"name":"双武器攻势","rank":4,"prereq":["双持娴熟"],"desc":"当你在副手持有具备轻型特性的武器时，使用该武器进行副手攻击的活力消耗减少3点。"},{"name":"双持防御","rank":4,"prereq":["双持娴熟"],"desc":"当你尝试用副手武器或副手盾牌进行防御反应时，活力消耗减少1点，最低为1点。"},{"name":"三连斩","rank":5,"prereq":["二连斩"],"desc":"你的剑刃以致命的精准翩然舞动。在任何二连斩之后，你立即对同一目标进行一次后续斩击。若命中，此攻击仅造成武器伤害（无奖励骰）。"},{"name":"致命打击","rank":5,"prereq":["强力一击"],"desc":"你的打击贯穿一切防御。当你对目标发动剑攻击或战斗技法并造成伤害时，你投出的每个爆发奖励骰（若有）所造成的伤害将直接作用于生命值或完整度。例如，如果你拥有一次奖励骰爆发，且爆发奖励骰（即奖励骰投出最大值后，你投出的第二颗骰子）结果为4，你将造成4点直接作用于生命值的伤害。"},{"name":"致命精准","rank":5,"prereq":["放倒"],"desc":"当你对近战目标发动匕首攻击时，你可以进行两次冒险，直取对手要害，所造成的伤害直接对生命值或完整性生效。"},{"name":"轻武器大师","rank":5,"prereq":["额外行动"],"desc":"当你进行轻武器攻击和行动掷骰时，你获得+1奖励骰（总计+3），并且你可以学习大师轻武器技法。"},{"name":"碎颅击","rank":5,"prereq":["破灭一击"],"desc":"当你成功命中的打属性武器攻击或战斗技法具有威胁或冲击时，你转而将该伤害直接对生命值或完整性造成。"},{"name":"双重侵袭","rank":5,"prereq":["双武器攻势"],"desc":"当你用主手武器抓住破绽时，若你的副手持有一把具有迅捷特性的武器，你可以消耗8点活力，并使用该迅捷武器发动一次副手追击攻击，相当于同时用两把武器抓住破绽。"},{"name":"双持打击","rank":5,"prereq":["双持防御"],"desc":"当你用副手的一把不具有两用特性的轻武器发动副手攻击时，你的攻击和伤害奖励骰不会承受任何挑战。"}]},
  {"skill":"防御","intro":"当你试图规避攻击时，你需要进行一次防御检定。与大多数技能不同，因为你将这些技能用作反应，它们通常会消耗活力。通常，你应将速度奖励骰加至防御反应中。 **特殊：防御反应。** 当你受到一次你察觉到的、来自武器或类似武器能力的攻击时，可采取防御反应，以期躲开该次攻击。防御技法有数种，如闪避、偏转和格挡。基础防御反应消耗5点活力，而高级防御技法消耗更多。你无法用防御来躲避你未察觉的攻击。","adv":[],"type":"反应","t1":"防御初学者","effect":"防御反应 +1 奖励骰；可使用偏转/格挡技法","nodes":[{"name":"防御初学者","rank":1,"prereq":[],"desc":"所有用于闪避攻击的防御反应获得+1奖励骰。你可以使用任何基础防御技法，如偏转和格挡。"},{"name":"躲闪","rank":2,"prereq":["防御初学者"],"desc":"当你徒手时，你的物防获得+5加值。"},{"name":"披甲自如","rank":2,"prereq":["防御初学者"],"desc":"穿着中型或重型护甲时，采取防御反应所承受的活力额外消耗减少3点。这使得你能更高效地使用闪避、偏转和格挡等防御技法，而不会耗尽你的耐力储备。"},{"name":"戒备","rank":2,"prereq":["防御初学者"],"desc":"当你使用盾牌或持有任何武器时，你的物防获得+5加值。"},{"name":"吸收","rank":3,"prereq":["躲闪"],"desc":"当你使用格挡反应时，可以减少等同于防御奖励骰数量3倍的额外伤害。例如，若你通过防御专家获得+2奖励骰，格挡时将额外抵消6点伤害。"},{"name":"防御专家","rank":3,"prereq":["披甲自如"],"desc":"你是防御专家。所有防御反应获得+1奖励骰（总计+2）。"},{"name":"阻截","rank":3,"prereq":["戒备"],"desc":"当你以盾牌或武器进行拨挡反应防御时，你可以将你的装备奖励骰（如果有）加到防御投骰上。"},{"name":"安全着陆","rank":4,"prereq":["吸收"],"desc":"当你受到坠落或爆炸伤害时，可使用防御反应。检定成功则伤害减半。"},{"name":"快步","rank":4,"prereq":["吸收"],"desc":"当你成功进行任何闪避反应时，你可以作为该反应的一部分移动至多10尺。"},{"name":"格挡反击","rank":4,"prereq":["防御专家"],"desc":"当你防御一次近战攻击时，你可以立即以2点挑战对攻击者进行一次免费的副手徒手或武器打击。"},{"name":"盾墙","rank":4,"prereq":["阻截"],"desc":"当你持用盾牌时，你针对远程攻击获得部分掩护。"},{"name":"堡垒","rank":4,"prereq":["阻截"],"desc":"当你穿着中型或重型护甲时，你的护甲等级在所有受到的攻击中+3。"},{"name":"岿然不动","rank":5,"prereq":["安全着陆"],"desc":"当你时，你免疫强制移动（推、拉、击倒），直到你的下个回合开始。"},{"name":"不破架势","rank":5,"prereq":["快步"],"desc":"当你防御反应失败时，你免疫来自那次攻击的击倒或束缚。"},{"name":"防御大师","rank":5,"prereq":["格挡反击"],"desc":"为所有防御反应增加+1奖励骰（总计+3）。"},{"name":"铁壁","rank":5,"prereq":["盾墙"],"desc":"当你使用盾牌防御一次攻击时，你免疫冲击效应或其他原本会绕过你盾牌的伤害。"},{"name":"披坚执锐","rank":5,"prereq":["堡垒"],"desc":"你深谙着甲行动之道。穿着中型和重型护甲时，你在运动检定中不会受到挑战。在计算护甲等级和伤害免疫时，你的护甲品质等级视为提高一级。"}]},
  {"skill":"学识","intro":"这个非常广泛的技能树涵盖了大量学科的一般与专业知识，例如历史、官僚制度、文学和哲学。你可能会被要求进行一次学识检定，以回忆起某段历史或传说，或理解某个文化典故。学识技能是关于学术知识的各个分支，例如传说与冷知识、现代史，或法规与法律。","adv":["学术洞察。 提升你学术理解的等阶，从而获得更深层的知识。","高效学习。 将学习与研究所需的时间减少20%。","分析精准。 提升你分析的准确度，额外提供1条信息。"],"type":"学术","t1":"初学者学识","effect":"学识检定 +1 奖励骰","nodes":[{"name":"初学者学识","rank":1,"prereq":[],"desc":"为所有学识（历史、文化、法律或学术分析）行动掷骰增加+1奖励骰。"},{"name":"学者","rank":2,"prereq":["初学者学识"],"desc":"你是某一学术领域公认的权威，受过将学术知识转化为实战工具的训练。你的专业知识让你能从研究中获取直接、可付诸实践的好处，将理论转化为切实的优势。选择一项： *历史：* 这涵盖了古代史、现代史、已消亡的文明，乃至当代事务等领域。当你使用历史先例来为某一行动辩护或拟定计划时，获得+1蓄势。 *法律：* 包括法律、官僚、组织研究及治理。你可以在休整期“起草”或“引用”一项法律先例，使你在次日的相关社交或类似谈判中获得+1奖励骰。 *文化：* 导力魔法、人文学科、哲学与人类学。你能识别并利用一个群体不成文的习俗，将对他们的社交检定VS降低最多15点。 *商业：* 你已广泛研究过货物。经济与贸易。你能通过一次学识检定，来成功评估一件物品的大致价值，该检定的VS为20，加上物品每个品质等级+5。 每当你成功通过一次涉及所选专业的学识检定时，你可以创造一份研究简报：一份关于你的发现的简洁、权威的记录。 研"},{"name":"学术档案","rank":3,"prereq":["学者"],"desc":"你维护着一套个人研究资料收藏。在游戏规则中，当你使用自己的档案（无论是便携还是固定设施），你在为分析文档、解读文字或交叉比对事实而进行的学识检定上，获得+1颗奖励骰。"},{"name":"专家学识","rank":3,"prereq":["学者"],"desc":"你的分析流程无与伦比。所有学识掷骰获得+1颗奖励骰（总计+2颗）。你能通过一次VS 25的检定，识别出伪造或篡改的记录。"},{"name":"田野笔记","rank":3,"prereq":["学者"],"desc":"你汇编精确的观察笔记。一旦你对某个文化或地点进行了至少一天的研究，盟友可以查阅你的笔记，此后在该地点或群体中进行的任何相关社交或调查掷骰上，获得+1颗奖励骰。"},{"name":"分析思维","rank":4,"prereq":["学术档案"],"desc":"你的学术追求锻炼了你的逻辑理解能力。你的理性属性值+8。","resource":{"rea":8}},{"name":"长久记忆","rank":4,"prereq":["学术档案"],"desc":"你的头脑以惊人的精确度存储细节。你的记忆属性值+8。","resource":{"mem":8}},{"name":"善学者","rank":4,"prereq":["专家学识"],"desc":"当尝试记忆新的图纸、公式、法术或技法时，你可以将你的学识奖励骰加入检定中。"},{"name":"文化洞察力","rank":4,"prereq":["田野笔记"],"desc":"你轻松地洞察人情与习俗。共情属性值+8","resource":{"emp":8}},{"name":"坚定意志","rank":4,"prereq":["田野笔记"],"desc":"你在高压中运用知识的实践锻炼了你的意志。决心属性值+8。","resource":{"rsl":8}},{"name":"数据综合","rank":5,"prereq":["分析思维"],"desc":"你擅长将不同的信息源联系起来。当交叉引用至少两个不同的档案时，你的学识检定获得+1蓄势。成功时，你还可以发现信息的隐藏或次要用途。"},{"name":"学术权威","rank":5,"prereq":["长久记忆"],"desc":"你的学识在正式或学术场合中具有不可否认的分量。在任何与你的专长相关的官方、学术或官僚场合中，你可以用学识代替社交进行检定。每场景一次，当提及你的名字、资历或声望时，你可以为任意盟友的检定增加+1奖励骰。"},{"name":"学识大师","rank":5,"prereq":["善学者"],"desc":"你是学术领域的大师。所有学识检定增加+1奖励骰（总计+3）。"},{"name":"应用观察","rank":5,"prereq":["文化洞察力"],"desc":"当观察现场或环境时，你可能会发现一个转瞬即逝的优势。通过5分钟的实地观察，你可以在你的回合中作为一个行动进行一次学识检定，VS 40。成功时，你为自己和同伴制定一项实地策略；向盟友呼喊，你可以获得以下好处之一： 为所观察的单个生物制造破绽。 给予所有聆听的盟友一项与你观察相关的特定技能检定+1蓄势。 针对一组敌人的攻击检定获得+1奖励骰。"},{"name":"智识坚城","rank":5,"prereq":["坚定意志"],"desc":"当你需要进行抵抗检定以对抗精神、模因或灵能侵袭时，你可以使用反应行动来调用学识并以你的学识技能增强该抵抗，消耗额外5点魔力，将你的学识奖励骰加入该次检定。"}]},
];

